{
  "sql": "SELECT COUNT(vi.seller_id), SUM(vi.price) FROM vw_ingresos_por_vendedor vi JOIN ( SELECT seller_id, AVG(review_score) AS avg_review_score, SUM(CASE WHEN order_delivered_customer_date > order_estimated_delivery_date THEN 1 ELSE 0 END) * 100.0 / COUNT(order_id) AS pct_late FROM vw_entregas_retrasos GROUP BY seller_id ) vtr ON vi.seller_id = vtr.seller_id WHERE vi.pedidos >= 30 AND (vtr.avg_review_score < 3.5 OR vtr.pct_late > 15)"
}
